toc, used = [], set()
def slug(text):
    s = re.sub(r"<[^>]+>", "", text)
    s = re.sub(r"[^a-z0-9]+", "-", html.unescape(s).lower()).strip("-")[:60] or "section"
    base, n = s, 2
    while s in used:
        s, n = f"{base}-{n}", n + 1
    used.add(s)
    return s
def add_id(m):
    level, inner = m.group(1), m.group(2)
    sid = slug(inner)
    toc.append((int(level), sid, re.sub(r"<[^>]+>", "", inner)))
    return f'<h{level} id="{sid}">{inner}</h{level}>'
body = re.sub(r"<h([23])>(.*?)</h\1>", add_id, body)

# Tables scroll inside their own container.
