nav.toc summary {{ display: none; }}
main {{ min-width: 0; }}
main > * {{ max-width: 76ch; }}
main > .table-wrap, main > .gallery, main > .handoff {{ max-width: none; }}
h2 {{ font: 700 28px/1.2 var(--font-display); letter-spacing: -.01em; margin: 56px 0 14px; padding-top: 14px; border-top: 2px solid var(--ink); text-wrap: balance; scroll-margin-top: 16px; }}
h3 {{ font: 600 20px/1.3 var(--font-display); margin: 34px 0 10px; text-wrap: balance; scroll-margin-top: 16px; }}
h4 {{ font: 600 14px/1.3 var(--font-display); letter-spacing: .08em; text-transform: uppercase; color: var(--muted); margin: 28px 0 8px; }}
main > h2:first-child {{ margin-top: 0; }}
p, ul, ol {{ margin: 0 0 14px; }}
li {{ margin: 3px 0; }} li > ul, li > ol {{ margin: 4px 0 6px; }}
strong {{ font-weight: 600; }}
code {{ font: 0.84em/1.4 var(--font-mono); background: var(--code-bg); padding: 1px 5px; border-radius: 3px; overflow-wrap: anywhere; }}
.table-wrap {{ overflow-x: auto; margin: 6px 0 20px; border: 1px solid var(--line); border-radius: 6px; background: var(--surface); }}
table {{ border-collapse: collapse; width: 100%; font: 14px/1.45 var(--font-display); font-variant-numeric: tabular-nums; }}
th, td {{ text-align: left; vertical-align: top; padding: 8px 12px; border-bottom: 1px solid var(--line); }}
th {{ font-weight: 600; color: var(--muted); font-size: 12.5px; letter-spacing: .03em; background: var(--code-bg); }}
tr:last-child td {{ border-bottom: 0; }}
td code {{ font-size: .86em; }}
.finding {{ display: flex; gap: 10px; align-items: baseline; margin-top: 26px; font: 600 17px/1.4 var(--font-display); }}
.sev {{ flex: none; font: 600 12px/1 var(--font-mono); padding: 4px 7px; border-radius: 4px; }}
.sev-high {{ background: var(--crit-soft); color: var(--crit); }} .sev-med {{ background: var(--warn-soft); color: var(--warn); }}
.handoff {{ background: var(--accent-soft); border: 1px solid var(--line); border-radius: 8px; padding: 6px 20px 20px; margin: 40px 0 8px; }}
.handoff h2 {{ border-top: 0; margin-top: 14px; padding-top: 0; }}
.handoff > p {{ max-width: 80ch; }}
.tasks {{ display: grid; gap: 18px; }}
.task {{ background: var(--surface); border: 1px solid var(--line); border-radius: 6px; padding: 16px 18px; min-width: 0; }}
.task-head {{ display: flex; gap: 16px; justify-content: space-between; align-items: flex-start; flex-wrap: wrap; }}
.task-head > div {{ min-width: 0; flex: 1 1 320px; }}
.task h3 {{ margin: 0 0 6px; }}
.task-why {{ font: 15px/1.5 var(--font-display); color: var(--muted); margin: 0 0 10px; max-width: 80ch; }}
.tags {{ display: flex; gap: 6px; flex-wrap: wrap; }}
.tag {{ font: 500 12px/1 var(--font-mono); padding: 4px 7px; border: 1px solid var(--line); border-radius: 4px; color: var(--muted); }}
button.copy {{ font: 600 14px/1 var(--font-display); color: var(--surface); background: var(--accent); border: 0; border-radius: 5px; padding: 10px 14px; cursor: pointer; min-height: 40px; }}
button.copy:hover {{ filter: brightness(1.08); }}
pre.brief {{ margin: 14px 0 0; max-height: 420px; overflow: auto; background: var(--code-bg); border: 1px solid var(--line); border-radius: 5px;
  padding: 14px 16px; font: 13px/1.55 var(--font-mono); white-space: pre-wrap; overflow-wrap: anywhere; }}
.gallery {{ display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 16px; margin: 8px 0 12px; }}
figure {{ margin: 0; background: var(--surface); border: 1px solid var(--line); border-radius: 6px; overflow: hidden; }}
figure img {{ display: block; width: 100%; height: auto; max-width: 100%; }}
figcaption {{ font: 13px/1.4 var(--font-display); color: var(--muted); padding: 8px 10px; }}
.mono {{ font-family: var(--font-mono); color: var(--accent); margin-right: 4px; }}
footer.foot {{ margin-top: 48px; border-top: 1px solid var(--line); padding-top: 14px; font: 13px/1.5 var(--font-display); color: var(--muted); }}
@media (max-width: 920px) {{
  .layout {{ grid-template-columns: minmax(0, 1fr); gap: 16px; }}
  nav.toc {{ position: static; max-height: none; border: 1px solid var(--line); border-radius: 6px; background: var(--surface); padding: 6px 10px; }}
  nav.toc summary {{ display: list-item; cursor: pointer; font-weight: 600; padding: 6px 0; }}
  body {{ font-size: 16px; }}
  h2 {{ font-size: 24px; }}
}}
</style>

<div class="wrap">
  <header class="masthead">
    <p class="eyebrow">Engineering appraisal &middot; 2026-10-15</p>
    <h1>coinpoker-help: Monitor frontend and repository progress</h1>
    <p class="meta">Branch checkpoint/seated-read-mechanism-2-20261002, HEAD 5889f14 plus the uncommitted refactor. Built from 68 agents with adversarial verification, live probes of the Monitor at 127.0.0.1:18090, and a full local test run (623 Rust and 814 Python tests passing).</p>
    <div class="verdict" role="list">
      <div class="stat warn" role="listitem"><div class="label">Monitor frontend</div><div class="value">5.6 / 10</div><div class="note">Trustworthy core, broken operator signals</div></div>
      <div class="stat warn" role="listitem"><div class="label">Repository overall</div><div class="value">C&minus; &middot; 55</div><div class="note">Strong guard-rails, perception worked once</div></div>
      <div class="stat ok" role="listitem"><div class="label">Definition of Done</div><div class="value">&asymp; 60%</div><div class="note">Met on 2026-10-12, not reproduced since</div></div>
      <div class="stat crit" role="listitem"><div class="label">Live seated advice</div><div class="value">&asymp; 25%</div><div class="note">Board, seated play, human review missing</div></div>
    </div>
  </header>
  <div class="layout">
    <nav class="toc" aria-label="Contents"><details open id="toc-details"><summary>Contents</summary>{toc_html}</details></nav>
    <main id="report">
{body}
      <footer class="foot">Source report and evidence: .local/reports/2026-10-15-appraisal/ in the repository (REPORT.md, screenshots, validation logs, raw agent output). Private receipts under .local/ are cited by path only.</footer>
    </main>
  </div>
</div>
<script>
(function () {{
  document.querySelectorAll("button.copy").forEach(function (button) {{
    button.addEventListener("click", function () {{
      var target = document.getElementById(button.getAttribute("data-target"));
      var text = target.textContent;
      var done = function () {{ button.textContent = "Copied"; setTimeout(function () {{ button.textContent = "Copy brief"; }}, 1800); }};
      var fallback = function () {{
        var range = document.createRange(); range.selectNodeContents(target);
        var sel = window.getSelection(); sel.removeAllRanges(); sel.addRange(range);
        button.textContent = "Selected: press Ctrl+C";
        setTimeout(function () {{ button.textContent = "Copy brief"; }}, 2600);
      }};
      try {{
        if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(done, fallback);
        else fallback();
      }} catch (e) {{ fallback(); }}
    }});
  }});
  var details = document.getElementById("toc-details");
  var narrow = window.matchMedia("(max-width: 920px)");
  var sync = function () {{ if (narrow.matches) details.removeAttribute("open"); else details.setAttribute("open", ""); }};
  sync();
  if (narrow.addEventListener) narrow.addEventListener("change", sync);
}})();
</script>
'''
out = OUT_DIR + r"\coinpoker-help-appraisal.html"
open(out, "w", encoding="utf-8").write(page)
print("written", out, round(len(page.encode()) / 1024), "KB; toc entries", len(toc), "; em dashes:", page.count("\u2014"))
